 <!-- ═══════════════════════════════════════════════════════════════
 Global kill-styles voor legacy floating action buttons.
 Hier in head zodat het werkt ook als oudere JS-versies nog
 in de service worker cache zitten (iOS/Android PWA).
 ═══════════════════════════════════════════════════════════════ -->
 <style id="dy-legacy-fab-kill">
 #dy-ai-fab,
 #dy-push-btn,
 #dy-hub-fab,
 #dy-hub-items,
 #dy-hub-backdrop,
 .dy-ai-fab,
 .dy-push-fab,
 .dy-floating-ai,
 .dy-floating-push {
 display: none !important;
 visibility: hidden !important;
 opacity: 0 !important;
 pointer-events: none !important;
 position: absolute !important;
 left: -9999px !important;
 top: -9999px !important;
 width: 0 !important;
 height: 0 !important;
 max-width: 0 !important;
 max-height: 0 !important;
 transform: scale(0) !im...chMedia('(display-mode: standalone)').matches || navigator.standalone);
 if (wasInstalled && !isStandalone) {
 var lastCheck = null;
 try { lastCheck = localStorage.getItem('dy_pwa_last_check'); } catch(e) {}
 var now = Date.now();
 if (lastCheck && (now - parseInt(lastCheck)) > 3600000) {
 setTimeout(function() {
 // Nogmaals controleren - kan zijn dat display-mode kortstondig fout was
 var stillNotStandalone = !(window.DY && typeof window.DY.isAppInstalled === 'function'
 ? window.DY.isAppInstalled()
 : (window.matchMedia('(display-mode: standalone)').matches || navigator.standalone));
 if (!stillNotStandalone) return;
 if (window.DY && typeof DY.trackPWAEvent === 'function') {
 DY.trackPWAEvent('removed');
 try {
 localStorage.removeItem('dy_install_v3');
 localStorage.removeItem('dy_pwa_geinstalleerd');
 } catch(e) {}
 }
 }, 5000);
 }
 }
 try { localStorage.setItem('dy_pwa_last_check', Date.now().toString()); } catch(e) {}
 })();
 </script>

</body>
</html>
'

